class Solution {
    public int findLHS(int[] nums) {
        java.util.HashMap<Integer, Integer> frequency = new java.util.HashMap<>();
        for (int value : nums) {
            frequency.put(value, frequency.getOrDefault(value, 0) + 1);
        }

        int best = 0;
        for (int value : frequency.keySet()) {
            if (frequency.containsKey(value + 1)) {
                best = Math.max(best, frequency.get(value) + frequency.get(value + 1));
            }
        }
        return best;
    }
}

class Solution {
    public int findLHS(int[] nums) {
        java.util.Arrays.sort(nums);
        int best = 0;
        int left = 0;
        for (int right = 0; right < nums.length; right++) {
            while (nums[right] - nums[left] > 1) {
                left++;
            }
            if (nums[right] - nums[left] == 1) {
                best = Math.max(best, right - left + 1);
            }
        }
        return best;
    }
}

class Solution {
    public int findLHS(int[] nums) {
        java.util.TreeMap<Integer, Integer> frequency = new java.util.TreeMap<>();
        for (int value : nums) {
            frequency.put(value, frequency.getOrDefault(value, 0) + 1);
        }

        int best = 0;
        for (int value : frequency.keySet()) {
            Integer nextCount = frequency.get(value + 1);
            if (nextCount != null) {
                best = Math.max(best, frequency.get(value) + nextCount);
            }
        }
        return best;
    }
}
